/* ENGINE FOG — 1:1 from silent-hill-decomp                              */
/* ==================================================================== */
typedef struct {
    float fogDistanceM;           /* meters (engine Q12 / 4096)   */
    uint8_t fogColor[3];          /* MAP_EFFECTS_INFOS[1]          */
    uint32_t worldTintQ12[3];     /* Q12(0.95/1.00/1.08)           */
    uint32_t field6Q12;           /* Q12(1.1) -> g_WorldEnvWork.field_20 */
} FogPreset;

/* MAP_EFFECTS_INFOS[1] — src/bodyprog/sys/map_info.c (THR outdoor street
 * preset, selected by world_effects.c D_800A9F80 = {1, 1})                  */
static const FogPreset FOG_PRESET_THR = {
    13.5f,                       /* fogDistance Q12(13.5)          */
    { 108, 100, 116 },           /* fogColor                       */
    { (uint32_t)(0.95f * 4096), (uint32_t)(1.00f * 4096), (uint32_t)(1.08f * 4096) },
    (uint32_t)(1.10f * 4096)     /* worldLightIntensity            */
};

typedef struct {
    /* g_WorldEnvWork.fog (subset) */
    int nearQ8, farQ8;            /* Q8: 256 units per meter */
    int depthShift;               /* 0x20 - Lzc(near-1)      */
    uint8_t fogRamp[128];         /* WorldEnv_FogDistanceSet LUT */
    int fogIntensity;             /* Q12                     */
    int isFogEnabled;
    uint8_t fogColor[3];          /* 0..255                  */
    uint8_t tintEff[3];           /* worldTint * field_20 (PS1 vertex color units) */
} EngineFog;

static int lzc32(uint32_t v) {            /* count leading zeros */
    if (v == 0) return 32;
    int n = 0;
    while (!(v & 0x80000000u)) { v <<= 1; n++; }
    return n;
}

/* D_800AE1C0 — bodyprog_80055028.c */
static const int FOG_CURVE[17] = {
    0x00, 0x00, 0x26, 0x4C, 0x5E, 0x70, 0x85, 0x99,
    0xB0, 0xBD, 0xD1, 0xDC, 0xE6, 0xF0, 0xF5, 0xFA, 0xFF
};

/* WorldEnv_FogDistanceSet(nearQ12, farQ12) — bodyprog_80055028.c 0x80055840 */
static void engine_fog_set_distances(EngineFog *f, int nearQ12, int farQ12) {
    int nearDist = nearQ12 >> 4;                    /* Q12_TO_Q8 */
    f->nearQ8 = nearDist;
    f->farQ8 = farQ12 >> 4;
    f->depthShift = 0x20 - lzc32((uint32_t)(nearDist - 1));

    int temp = (int)((0x10u << (f->depthShift + 1)) / (uint32_t)nearDist);
    int var_t0 = 0, i = 0;
    for (; var_t0 < 4096 && i < 0x80; var_t0 += temp, i++) {
        int var_v1, var_a0, var_a1, var_a2;
        int x = var_t0 >> 8;
        if (x == 0) {
            var_a1 = 0x80;
            var_a2 = var_t0 & 0x7F;
            if (var_t0 & 0x80) { var_v1 = FOG_CURVE[0]; var_a0 = 0; }
            else               { var_a0 = FOG_CURVE[0]; var_v1 = FOG_CURVE[1]; }
        } else {
            var_a1 = 0x100;
            var_a2 = var_t0 & 0xFF;
            var_a0 = FOG_CURVE[x];
            var_v1 = FOG_CURVE[x + 1];
        }
        int lo = (var_a0 * (var_a1 - var_a2) + var_v1 * var_a2) / var_a1;
        f->fogRamp[i] = (uint8_t)clampi(lo, 0, 0xFF);
    }
    for (; i < 0x80; i++) f->fogRamp[i] = 0xFF;
}

/* func_800559A8(depthQ12) — Q12 fog factor via LUT interp */
static int engine_fog_ramp_lookup_q12(const EngineFog *f, int depthQ12) {
    int temp_v0 = 1 << f->depthShift;
    int var_a1 = temp_v0 >> 7;
    int t = depthQ12 >> 4;                     /* Q12 -> Q8 */
    int idx = t / var_a1;
    if (idx < 0) return 0;
    if (idx >= 0x80) return 4096;
    int a = f->fogRamp[idx] * 16;
    int frac = t % var_a1;
    int b = (idx == 0x7F) ? 4096 : (f->fogRamp[idx + 1] * 16);
    return a + (b - a) * frac / var_a1;
}

/* func_80055814(fogDistance) -> fog.intensity = 1 - rampLookup(fogDistance) */
static void engine_fog_update_intensity(EngineFog *f, int fogDistanceQ12) {
    f->fogIntensity = 4096 - engine_fog_ramp_lookup_q12(f, fogDistanceQ12);
}

/* func_80055A50-equivalent used by func_80057B7C: z is RAW Q8 (field_18C/SZ) */
static int engine_fog_vertex(const EngineFog *f, int zQ8) {
    if (zQ8 < 0) zQ8 = 0;
    if (zQ8 >= (1 << f->depthShift)) return 255;
    return f->fogRamp[(zQ8 << 7) >> f->depthShift];
}

/* engine func_80055A50 — exact, with the >>4 temp shift the SNOW path uses
 * (it is fed the raw stszotz OTZ there, not the pre-shifted Q8 value) */
static int engine_fog_80055A50(const EngineFog *f, int x) {
    int temp = x >> 4;
    if (temp >= (1 << f->depthShift)) return 255;
    return f->fogRamp[(temp << 7) >> f->depthShift];
}

/* WorldEnv_Init + WorldEnv_FogParamsSet + WorldEnv_FogLightingParamsUpdate
 * for the THR outdoor preset MAP_EFFECTS_INFOS[1].                            */
static void engine_fog_init_from_preset(EngineFog *f, const FogPreset *p) {
    f->isFogEnabled = 1;                       /* field_E = 1 */
    f->fogColor[0] = p->fogColor[0];
    f->fogColor[1] = p->fogColor[1];
    f->fogColor[2] = p->fogColor[2];

    int nearQ12 = (int)(p->fogDistanceM * 4096.0f + 0.5f);
    int farQ12 = nearQ12 + 4096;               /* + Q12(1.0) per FogLightingParamsUpdate */
    engine_fog_set_distances(f, nearQ12, farQ12);
    engine_fog_update_intensity(f, nearQ12);

    /* worldTintColor = tintQ12 >> 5  (WorldEnv_WorldLightingParamSet) */
    int tint[3];
    for (int c = 0; c < 3; c++) tint[c] = (int)p->worldTintQ12[c] >> 5;
    /* Gfx_MeshDraw pre-pass: field_8 = dpcs(DP=4096-field_20, RGB=tint, FC=0)
     *   -> out = tint * field_20 / 4096  (saturating, DPCS 8-bit output)   */
    for (int c = 0; c < 3; c++) {
        int v = (int)((int64_t)tint[c] * (int64_t)p->field6Q12 / 4096);
        f->tintEff[c] = (uint8_t)clampi(v, 0, 255);
    }
}

